      "attributionText": "Pagkilala sa opisyal na pinagmulan at radar sa pagtuklas ng konsyerto. Ang opisyal na data ng tiket ay ibinibigay ng Live Nation Asia, LOKET, BBO Events, at mga opisyal na daluyan ng promoter (Color Asia Live, Plainsong Live, Ismaya Live, Dyandra Global, TEM Presents, PK Entertainment). Ang mga daluyan ng radar ng pagtuklas ng konsyerto na Songkick at Bandsintown (Jakarta at Greater Jakarta) ay ginagamit para sa pagsubaybay ng mga tour at lahat ng entri ay sinusuri laban sa mga opisyal na daluyan ng tagapagtanghal/promoter bago ilathala. Nag-iimbak lamang ang TIKUM ng mga makatotohanang data (pamagat ng kaganapan, petsa, venue, lungsod, presyo, at mga opisyal na link/poster na may kredito sa promoter) at hindi kumokopya ng mga pang-promosyong materyal. Ang mga Instagram channel na @infokonser, @livenationasia, at @ticketmasterasia ay nagsisilbing senyales ng pagtuklas (Tier 3) at hindi kailanman ginagamit bilang awtoridad sa beripikasyon."
