      "step1Title": "เลือกงานอีเวนต์และบัตรที่ผ่านการตรวจสอบ:",
      "step1DescHtml": "ค้นหาคอนเสิร์ตหรืออีเวนต์ใน <a href=\"/events\" style=\"color:#E36F45;\">แคตตาล็อกงานอีเวนต์</a> ข้อมูลอีเวนต์ทั้งหมดผ่านการตรวจสอบวัน เวลา สถานที่ และแหล่งที่มาทางการของผู้จัดงาน",
      "step2Title": "เลือกซื้อทันที (Buy Now) หรือยื่นข้อเสนอราคา (Make Offer):",
      "step2Desc": "ซื้อทันทีด้วยราคารวมทั้งหมดที่โปร่งใส หรือยื่นข้อเสนอราคาแบบมีโครงสร้าง (ขั้นต่ำ 50% ของราคาที่ตั้งไว้) โดยไม่ต้องเจรจานอกแพลตฟอร์ม",
      "step3Title": "รายละเอียดราคาโปร่งใสที่หน้าชำระเงินและการพักเงินภายใต้การดูแลของแพลตฟอร์ม:",
