      "faq1Q": "นิติบุคคลใดเป็นผู้ดำเนินการแพลตฟอร์ม TIKUM?",
      "faq1A": "TIKUM ดำเนินการอย่างเป็นทางการภายใต้บริษัท PT SHINERVA PRAJNA TEJAS นิติบุคคลที่จดทะเบียนในเมืองบันดุง ชวาตะวันตก ประเทศอินโดนีเซีย",
      "faq2Q": "อัตราค่าบริการ Dual-Tier V2 ของ TIKUM เป็นอย่างไร?",
      "faq2A": "ภายใต้นโยบาย Dual-Tier V2 ตัวเลือกผู้ขายโอนเอง (SELLER_MANAGED) มีค่าบริการผู้ซื้อ 6% + ผู้ขาย 6% (ขั้นต่ำ IDR 35,000, สูงสุด IDR 300,000/ใบ) และตัวเลือกมีเจ้าหน้าที่ PIC หน้างาน (TIKUM_VENUE_PIC) มีค่าบริการผู้ซื้อ 9% + ผู้ขาย 9% (ขั้นต่ำ IDR 35,000, สูงสุด IDR 450,000/ใบ)",
      "faq3Q": "จะเกิดอะไรขึ้นหากบัตรของฉันถูกปฏิเสธที่ประตูทางเข้าสถานที่จัดงาน?",
      "faq3A": "หากบัตรถูกปฏิเสธโดยเครื่องสแกนที่ประตูทางเข้างาน โปรดแจ้งข้อพิพาทผ่านหน้า /track หรือติดต่อฝ่ายบริการลูกค้า เมื่อตรวจสอบหลักฐานเรียบร้อยแล้ว คุณจะได้รับการคุ้มครองคืนเงินเต็มจำนวนตามนโยบายการคืนเงินของ Tikum",
      "faq4Q": "การชำระเงินจริงเปิดใช้งานบนหน้าชำระเงิน (/pay) แล้วหรือยัง?",
      "faq4A": "ขณะนี้หน้าชำระเงินเชื่อมต่อกับ DOKU Direct API ในโหมด Sandbox และช่วงเตรียมเปิดตัว จึงไม่มีการตัดเงินจริงจากบัญชีหรือบัตรของผู้ใช้งานระหว่างการทดสอบและตรวจสอบระบบ"
