      "emptyDisputesTitle": "ไม่มีข้อพิพาทที่เปิดอยู่ (0)",
      "emptyDisputesDesc": "ธุรกรรมทั้งหมดของคุณดำเนินไปตามปกติ ไม่มีคำร้องข้อพิพาทค้างอยู่",
